13	/** Seconds left on Scalable's preview, ticking once a second; null for cards without one. */
14	function useSecondsLeft(expiresAt: string | null) {
15	  const left = () => expiresAt ? Math.max(0, Math.floor((Date.parse(expiresAt) - Date.now()) / 1000)) : null;
16	  const [seconds, setSeconds] = useState(left);
17	  useEffect(() => {
18	    if (!expiresAt) return;
19	    const timer = setInterval(() => setSeconds(left()), 1000);
20	    return () => clearInterval(timer);
21	    // eslint-disable-next-line react-hooks/exhaustive-deps
22	  }, [expiresAt]);
23	  return seconds;
24	}
