26	      compare={compare && { name: compare.name, values: compare.days.map(day => major(day.expectedMinor, currency)) }} />
27	    <p className="text-xs text-muted-foreground">Shaded band runs from conservative to optimistic. Chart coordinates are approximate; exact amounts appear below.</p>
28	    <dl className="grid gap-3 sm:grid-cols-3">{([["Expected", last.expectedMinor], ["Conservative", last.conservativeMinor], ["Optimistic", last.optimisticMinor]] as const).map(([label, amount]) =>
29	      <div key={label} className="rounded-lg bg-muted/60 px-4 py-3"><dt className="text-xs text-muted-foreground">{label} at horizon</dt><dd className="mt-1 font-mono text-base font-semibold">{money(amount)}</dd></div>)}</dl>
