      <span style={{ width: 16, height: 16, flexShrink: 0, borderRadius: "50%", background: c.lime }} />
      <div><div style={{ fontSize: 28, fontWeight: 500 }}>{name}</div><div style={{ fontSize: 23, color: c.mutedFg }}>{status}</div></div>
    </div></Pop>)}
  </Scene>;
