import { c, Card, font, IN_OUT, lerp, money, Pop, ramp, Rise, Scene, Slam, useT } from "../kit";
import { CUES, SCENES } from "../timeline";

type Row = { name: string; spent: number; limit: number; note: string; over?: boolean; adds?: number };
// The €42 from the call lands in Eating out, so its note matches Moneo's rule: under a quarter left shows days left.
const ROWS: Row[] = [
  { name: "Groceries", spent: 312, limit: 450, note: "On track" },
  { name: "Eating out", spent: 146, adds: 42, limit: 200, note: "€12.00 left for 9 days" },
  { name: "Going out", spent: 240, limit: 200, note: "€40.00 over", over: true },
  { name: "Travel", spent: 120, limit: 300, note: "€180.00 left · includes €80.00 rolled over from October" },
];

export function Budget() {
  const t = useT();
  return <Scene seconds={SCENES.budget.seconds}>
    <Slam word="Budget it." sub="Set a limit once. Moneo keeps score from your real spending." settle={0.4} />
    <Rise at={0.6} by={50} style={{ position: "absolute", left: 90, right: 90, top: 200 }}>
      <Card style={{ padding: "34px 44px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", fontSize: 32, fontWeight: 500 }}><span>Budgets</span><span style={{ fontFamily: font.mono, fontSize: 24, color: c.mutedFg }}>November</span></div>
        <div style={{ display: "grid", gap: 30, marginTop: 30 }}>
          {ROWS.map((row, index) => {
            const start = 0.75 + index * 0.1;
            const fill = ramp(t, start, start + 0.7, IN_OUT);
            const spent = row.spent * fill + (row.adds ?? 0) * ramp(t, CUES.budgetAdd, CUES.budgetAdd + 0.4);
            const share = Math.min(100, spent / row.limit * 100);
            const color = row.over && spent > row.limit ? c.warning : share >= 90 ? c.fg : c.lime;
            return <div key={row.name}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", fontSize: 36, fontWeight: 500 }}>
                <span>{row.name}</span><span style={{ fontFamily: font.mono, fontSize: 32, color: row.over && spent > row.limit ? c.warning : c.fg, fontVariantNumeric: "tabular-nums" }}>{money(spent)} / {money(row.limit)}</span>
              </div>
              <div style={{ height: 14, marginTop: 12, borderRadius: 99, background: c.muted }}><div style={{ height: "100%", width: `${share}%`, borderRadius: 99, background: color }} /></div>
              <div style={{ marginTop: 9, fontSize: 26, color: row.over ? c.warning : c.mutedFg, opacity: ramp(t, start + 0.65, start + 0.9) }}>{row.note}</div>
            </div>;
          })}
        </div>
      </Card>
    </Rise>
    <Pop at={CUES.budgetAdd} from={0.7} style={{ position: "absolute", left: 800, top: 415, zIndex: 8, opacity: 1 - ramp(t, 3.0, 3.3) }}>
      <div style={{ padding: "12px 24px", borderRadius: 14, background: c.aiSoft, border: `1px solid ${c.aiBorder}`, color: c.ai, fontFamily: font.mono, fontSize: 28, transform: `translateY(${lerp(30, 0, ramp(t, CUES.budgetAdd, CUES.budgetAdd + 0.3))}px)` }}>+€42 Trattoria, from your call</div>
    </Pop>
  </Scene>;
}

import { c, Card, Cursor, Eyebrow, font, IN_OUT, lerp, money, Pop, ramp, Rise, Scene, Slam, smoothPath, useT, whole } from "../kit";
import { CUES, SCENES } from "../timeline";

const MONTHS = ["Nov", "Dec", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov"];
// Expected cash each month. June is the €3,180 Moneo quoted on the call, after Lisbon.
const EXPECTED = [6420, 5900, 5200, 5650, 6100, 6400, 4980, 3180, 3900, 4600, 5300, 6000, 6700];
const W = 1120, H = 430, MAX = 11000;
const x = (index: number) => index * (W / (EXPECTED.length - 1));
const y = (value: number) => H - value / MAX * H;

export function Plan() {
  const t = useT();
  const reveal = ramp(t, 0.75, 2.2, IN_OUT);
  const extra = 200 * ramp(t, CUES.planWhatIf, CUES.planWhatIf + 1.3, IN_OUT);
  const shifted = EXPECTED.map((value, index) => value + extra * index);
  const line = smoothPath(shifted.map((value, index) => [x(index), y(value)]));
  const band = (spread: number) => shifted.map((value, index): [number, number] => [x(index), y(value + spread * spread * index * 42 * Math.sign(spread))]);
  const upper = band(9), lower = band(-9).reverse();
  const bandPath = `${smoothPath(upper)}L${lower[0][0]},${lower[0][1]}${smoothPath(lower).replace(/^M[^C]+/, "")}Z`;
  const base = smoothPath(EXPECTED.map((value, index) => [x(index), y(value)]));
  const thumb = lerp(0, 40, ramp(t, CUES.planWhatIf, CUES.planWhatIf + 1.3, IN_OUT));
  const goal = 18400 + extra * 6;
  return <Scene seconds={SCENES.plan.seconds}>
    <Slam word="Plan it." sub="See the next twelve months, then try out a different one." />
    <Rise at={0.65} by={50} style={{ position: "absolute", left: 90, top: 200, width: 1250 }}>
      <Card style={{ height: 800, padding: 36 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
          <div><Eyebrow>Expected in Nov 2027</Eyebrow><div style={{ fontFamily: font.display, fontSize: 88, fontWeight: 500, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{money(shifted.at(-1)! * lerp(0.8, 1, reveal))}</div></div>
          <div style={{ opacity: ramp(t, CUES.planWhatIf, CUES.planWhatIf + 0.3), fontFamily: font.mono, fontSize: 28, color: c.ai, border: `1px solid ${c.aiBorder}`, background: c.aiSoft, padding: "10px 18px", borderRadius: 12 }}>what-if</div>
        </div>
        <svg viewBox={`-10 -10 ${W + 20} ${H + 60}`} style={{ width: "100%", marginTop: 26, overflow: "visible" }}>
          <defs><clipPath id="planClip"><rect x="-20" y="-40" width={(W + 40) * reveal} height={H + 120} /></clipPath></defs>
          <g clipPath="url(#planClip)">
            <path d={bandPath} fill={c.lime} opacity=".09" />
            {extra > 0 && <path d={base} fill="none" stroke={c.chartOut} strokeWidth="3" strokeDasharray="8 10" />}
            <path d={line} fill="none" stroke={c.lime} strokeWidth="5" strokeLinecap="round" />
            {[6, 7].map(index => <circle key={index} cx={x(index)} cy={y(shifted[index])} r="9" fill={c.bg} stroke={c.lime} strokeWidth="4" />)}
          </g>
          {MONTHS.map((month, index) => index % 2 === 0 ? <text key={index} x={x(index)} y={H + 44} textAnchor="middle" fill={c.subtle} fontFamily={font.mono} fontSize="22">{month}</text> : null)}
          <g opacity={ramp(t, 1.75, 2.0)} transform={`translate(${x(7)} ${y(shifted[7]) + 44})`}>
            <text textAnchor="middle" fill={c.fg} fontFamily={font.sans} fontSize="26" fontWeight="500">Lisbon −€1,800</text>
          </g>
        </svg>
      </Card>
    </Rise>
    <Pop at={1.0} from={0.92} style={{ position: "absolute", left: 1370, top: 200, width: 460 }}>
      <Card style={{ background: c.aiSoft, borderColor: c.aiBorder, height: 390 }}>
        <div style={{ fontSize: 28, fontWeight: 500, color: c.ai }}>What if…</div>
        <div style={{ fontSize: 34, lineHeight: 1.18, marginTop: 14, fontWeight: 500 }}>I save <span style={{ fontFamily: font.mono, color: c.lime }}>{whole(extra)}</span> more each month?</div>
        <div style={{ position: "relative", height: 12, marginTop: 56, borderRadius: 99, background: c.input }}>
          <div style={{ width: `${thumb * 2.05}%`, height: "100%", background: c.lime, borderRadius: 99 }} />
          <div style={{ position: "absolute", left: `${thumb * 2.05}%`, top: -15, marginLeft: -21, width: 42, height: 42, borderRadius: "50%", background: c.fg, boxShadow: "0 4px 14px rgb(0 0 0 / .5)" }} />
        </div>
        <div style={{ fontSize: 25, color: c.mutedFg, marginTop: 36 }}>Nothing changes until you save it.</div>
      </Card>
    </Pop>
