14	const read = key => text.match(new RegExp(`^${key}=(.*)$`, "m"))?.[1].trim().replace(/^"(.*)"$/, "$1") ?? "";
15	const write = (key, value) => {
16	  const line = `${key}=${value}`;
17	  text = new RegExp(`^${key}=.*$`, "m").test(text) ? text.replace(new RegExp(`^${key}=.*$`, "m"), line) : `${text.trimEnd()}\n${line}\n`;
18	};
