23	
24	const secret = (bytes = 32) => randomBytes(bytes).toString("base64url");
25	const jwt = (role, key) => {
26	  const part = value => Buffer.from(JSON.stringify(value)).toString("base64url");
27	  const body = `${part({ alg: "HS256", typ: "JWT" })}.${part({ iss: "supabase", role, iat: Math.floor(Date.now() / 1000), exp: Math.floor(Date.now() / 1000) + 10 * 365 * 86_400 })}`;
28	  return `${body}.${createHmac("sha256", key).update(body).digest("base64url")}`;
29	};
