31	const generated = [];
32	const ensure = (key, make) => { if (!read(key)) { write(key, make()); generated.push(key); } };
33	ensure("POSTGRES_PASSWORD", () => secret(24));
34	ensure("JWT_SECRET", () => secret(48));
35	// The API keys are signed with JWT_SECRET, so they are remade whenever it is new.
36	if (generated.includes("JWT_SECRET") || !read("SUPABASE_SERVICE_ROLE_KEY")) {
