38	  write("SUPABASE_SERVICE_ROLE_KEY", jwt("service_role", read("JWT_SECRET")));
39	}
40	const apiPort = read("API_PORT") || "54321", dbPort = read("DB_PORT") || "54322";
41	write("NEXT_PUBLIC_SUPABASE_URL", `http://127.0.0.1:${apiPort}`);
42	write("SUPABASE_DB_URL", `postgresql://postgres:${read("POSTGRES_PASSWORD")}@127.0.0.1:${dbPort}/postgres`);
43	ensure("NEXT_PUBLIC_APP_URL", () => "http://localhost:3000");
44	ensure("BANK_TOKEN_ENCRYPTION_KEY", () => randomBytes(32).toString("base64"));
