67	  const applied = new Set((await db`select version from supabase_migrations.schema_migrations`).map(row => row.version));
68	  const pending = readdirSync("supabase/migrations").filter(file => file.endsWith(".sql")).sort().filter(file => !applied.has(file.split("_")[0]));
69	  for (const file of pending) {
70	    const source = readFileSync(`supabase/migrations/${file}`, "utf8"), version = file.split("_")[0];
71	    await db.begin(async tx => {
72	      await tx.unsafe(source);
73	      await tx`insert into supabase_migrations.schema_migrations (version, name, statements) values (${version}, ${file.slice(version.length + 1, -4)}, ${[source]})`;
74	    });
75	  }
76	  console.log(pending.length ? `Applied ${pending.length} migration(s).` : "Database is up to date.");
77	  // PostgREST caches the schema; reload it after migrations.
78	  if (pending.length) await db`notify pgrst, 'reload schema'`;
79	} finally {
80	  await db.end();
81	}
