63	/** A browser whose fake mic plays `wav`, logging the call's data-channel events (not transcripts or audio). */
64	async function open(wav) {
65	  const browser = await chromium.launch({ args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream", `--use-file-for-fake-audio-capture=${wav}`, "--autoplay-policy=no-user-gesture-required"] });
66	  const context = await browser.newContext({ storageState: "e2e/.auth.json", permissions: ["microphone"] });
67	  const page = await context.newPage();
68	  const log = [], chats = [], timing = {};
69	  page.on("response", async response => {
70	    if (!response.url().endsWith("/api/chat") || response.request().method() !== "POST") return;
71	    const request = JSON.parse(response.request().postData() ?? "{}");
72	    const text = await response.text().catch(() => "");
73	    const result = text.trim().split("\n").map(line => { try { return JSON.parse(line); } catch { return null; } }).find(event => event?.type === "result");
74	    chats.push({ message: request.message, via: request.context?.via, status: result?.status ?? response.status(), error: result?.body?.error });
75	    console.log("chat", chats.at(-1));
76	  });
77	  page.on("console", message => {
78	    const text = message.text();
79	    if (text.startsWith("[call] started")) timing.sessionStartedAt ??= Date.now();
80	    if (text.startsWith("[call] spoke")) timing.firstWordsAt ??= Date.now();
81	    if (text.startsWith("[call]")) { log.push(text); if (!text.startsWith("[call] spoke")) console.log(text.slice(0, 220)); }
82	    else if (message.type() === "error") console.log(text);
83	  });
84	  await page.addInitScript(() => {
85	    const create = RTCPeerConnection.prototype.createDataChannel;
86	    RTCPeerConnection.prototype.createDataChannel = function (...args) {
87	      const channel = create.apply(this, args);
88	      channel.addEventListener("message", message => {
89	        const event = JSON.parse(message.data);
90	        if (event.type === "session.started") console.log("[call] started voice=" + event.session?.audio?.output?.voice);
91	        else if (event.type === "session.output_transcript.delta") console.log("[call] spoke " + (event.delta ?? ""));
92	        else if (!/delta|usage/.test(event.type)) console.log("[call]", event.type, JSON.stringify(event).slice(0, 200));
93	      });
94	      const send = channel.send.bind(channel);
95	      channel.send = data => { console.log("[call] sent", String(data).slice(0, 200)); send(data); };
96	      return channel;
97	    };
98	  });
99	  return { browser, page, log, chats, timing };
100	}
