await slider.evaluate(el => { window.__events = []; for (const type of ["pointerdown", "mousedown", "input", "change"]) el.addEventListener(type, () => window.__events.push(type)); document.addEventListener("pointerdown", event => window.__events.push("doc:" + event.target.tagName), true); });
const box = await slider.boundingBox();
