  ] } as Scene,
  ask: { word: "Ask it.", bg: "lime", beats: 8, clips: [
    { shot: "chat", from: 1, to: 3.5, src: 1.6, rate: 2, cam: { x: 1152, y: 540, z: 1.9 } },
